// buildConfigVersionWhere recursively builds a WHERE clause string and arguments.
func buildConfigVersionWhere(c *Client, wheres []query.ConfigVersionWhereClause, argIdx *int) (string, []any) {
	var parts []string
	var args []any
	for _, w := range wheres {
		switch w.Field {
		case "__AND__":
			if subs, ok := w.Value.([]query.ConfigVersionWhereClause); ok {
				sub, subArgs := buildConfigVersionWhere(c, subs, argIdx)
				if sub != "" {
					parts = append(parts, "("+sub+")")
				}
				args = append(args, subArgs...)
			}
		case "__OR__":
			if subs, ok := w.Value.([]query.ConfigVersionWhereClause); ok {
				var orParts []string
				for _, sc := range subs {
					sub, subArgs := buildConfigVersionWhere(c, []query.ConfigVersionWhereClause{sc}, argIdx)
					if sub != "" {
						orParts = append(orParts, sub)
					}
					args = append(args, subArgs...)
				}
				if len(orParts) > 0 {
					parts = append(parts, "("+strings.Join(orParts, " OR ")+")")
				}
			}
		case "__NOT__":
			if sc, ok := w.Value.(query.ConfigVersionWhereClause); ok {
				sub, subArgs := buildConfigVersionWhere(c, []query.ConfigVersionWhereClause{sc}, argIdx)
				if sub != "" {
					parts = append(parts, "NOT ("+sub+")")
				}
				args = append(args, subArgs...)
			}
		default:
			switch w.Operator {
			case "IS NULL":
				parts = append(parts, w.Field+" IS NULL")
			case "IN", "NOT IN":
				if vals, ok := w.Value.([]any); ok {
					if len(vals) == 0 {
						if w.Operator == "IN" {
							parts = append(parts, "1 = 0")
						} else {
							parts = append(parts, "1 = 1")
						}
					} else {
						phs := make([]string, len(vals))
						for i, v := range vals {
							*argIdx++
							phs[i] = c.placeholder(*argIdx)
							args = append(args, v)
						}
						parts = append(parts, w.Field+" "+w.Operator+" ("+strings.Join(phs, ", ")+")")
					}
				}
			case "CONTAINS":
				*argIdx++
				parts = append(parts, w.Field+" LIKE "+c.placeholder(*argIdx)+" ESCAPE '\\'")
				args = append(args, "%"+escapeLikePattern(fmt.Sprint(w.Value))+"%")
			case "STARTS_WITH":
				*argIdx++
				parts = append(parts, w.Field+" LIKE "+c.placeholder(*argIdx)+" ESCAPE '\\'")
				args = append(args, escapeLikePattern(fmt.Sprint(w.Value))+"%")
			case "ENDS_WITH":
				*argIdx++
				parts = append(parts, w.Field+" LIKE "+c.placeholder(*argIdx)+" ESCAPE '\\'")
				args = append(args, "%"+escapeLikePattern(fmt.Sprint(w.Value)))
			default:
				*argIdx++
				parts = append(parts, w.Field+" "+w.Operator+" "+c.placeholder(*argIdx))
				args = append(args, w.Value)
			}
		}
	}
	return strings.Join(parts, " AND "), args
}

