func (b NodeUpdateBuilder) combinedWhere() (query.NodeWhereClause, error) {
	if len(b.wheres) == 0 {
		return query.NodeWhereClause{}, fmt.Errorf("Node.Update.Do: no where clause provided")
	}
	if len(b.wheres) == 1 {
		return b.wheres[0], nil
	}
	return query.Node.AND(b.wheres...), nil
}

// Do executes the staged update as a single-row update.
