// Aggregate computes aggregate values for Node.
func (a NodeActions) Aggregate(ctx context.Context, opts ...query.NodeAggregateOption) (*query.NodeAggregateResult, error) {
	selParts := []string{"COUNT(*)"}
	for _, opt := range opts {
		selParts = append(selParts, fmt.Sprintf("%s(%s)", strings.ToUpper(opt.Fn), opt.Field))
	}
	q := fmt.Sprintf("SELECT %s FROM nodes", strings.Join(selParts, ", "))
	row := a.client.executor.QueryRowContext(ctx, q)
	result := &query.NodeAggregateResult{
		Avg: make(map[string]*float64),
		Sum: make(map[string]*float64),
		Min: make(map[string]any),
		Max: make(map[string]any),
	}
	aggVals := make([]sql.NullFloat64, len(opts))
	scanDest := make([]any, 0, 1+len(opts))
	scanDest = append(scanDest, &result.Count)
	for i := range opts {
		scanDest = append(scanDest, &aggVals[i])
	}
	if err := row.Scan(scanDest...); err != nil {
		return nil, fmt.Errorf("Node.Aggregate: %w", err)
	}
	for i, opt := range opts {
		if aggVals[i].Valid {
			v := aggVals[i].Float64
			switch opt.Fn {
			case "avg":
				result.Avg[opt.Field] = &v
			case "sum":
				result.Sum[opt.Field] = &v
			case "min":
				result.Min[opt.Field] = v
			case "max":
				result.Max[opt.Field] = v
			}
		}
	}
	return result, nil
}

// GroupBy performs a GROUP BY query on Node.
func (a NodeActions) GroupBy(ctx context.Context, fields []string, opts ...query.NodeAggregateOption) ([]query.NodeGroupByResult, error) {
	selParts := make([]string, 0, len(fields)+1+len(opts))
	selParts = append(selParts, fields...)
	selParts = append(selParts, "COUNT(*)")
	for _, opt := range opts {
		selParts = append(selParts, fmt.Sprintf("%s(%s)", strings.ToUpper(opt.Fn), opt.Field))
	}
	q := fmt.Sprintf("SELECT %s FROM nodes GROUP BY %s",
		strings.Join(selParts, ", "), strings.Join(fields, ", "))
	rows, err := a.client.executor.QueryContext(ctx, q)
	if err != nil {
		return nil, fmt.Errorf("Node.GroupBy: %w", err)
	}
	defer rows.Close()
	var results []query.NodeGroupByResult
	for rows.Next() {
		r := query.NodeGroupByResult{
			Group: make(map[string]any),
			Avg:   make(map[string]*float64),
			Sum:   make(map[string]*float64),
			Min:   make(map[string]any),
			Max:   make(map[string]any),
		}
		groupVals := make([]any, len(fields))
		scanDest := make([]any, 0, len(fields)+1+len(opts))
		for i := range fields {
			groupVals[i] = new(any)
			scanDest = append(scanDest, groupVals[i])
		}
		scanDest = append(scanDest, &r.Count)
		aggVals := make([]sql.NullFloat64, len(opts))
		for i := range opts {
			scanDest = append(scanDest, &aggVals[i])
		}
		if err := rows.Scan(scanDest...); err != nil {
			return nil, fmt.Errorf("Node.GroupBy scan: %w", err)
		}
		for i, f := range fields {
			r.Group[f] = *(groupVals[i].(*any))
		}
		for i, opt := range opts {
			if aggVals[i].Valid {
				v := aggVals[i].Float64
				switch opt.Fn {
				case "avg":
					r.Avg[opt.Field] = &v
				case "sum":
					r.Sum[opt.Field] = &v
				case "min":
					r.Min[opt.Field] = v
				case "max":
					r.Max[opt.Field] = v
				}
			}
		}
		results = append(results, r)
	}
	return results, rows.Err()
}

// buildOriginPoolWhere recursively builds a WHERE clause string and arguments.
func buildOriginPoolWhere(c *Client, wheres []query.OriginPoolWhereClause, argIdx *int) (string, []any) {
	var parts []string
	var args []any
	for _, w := range wheres {
		switch w.Field {
		case "__AND__":
			if subs, ok := w.Value.([]query.OriginPoolWhereClause); ok {
				sub, subArgs := buildOriginPoolWhere(c, subs, argIdx)
				if sub != "" {
					parts = append(parts, "("+sub+")")
				}
				args = append(args, subArgs...)
			}
		case "__OR__":
			if subs, ok := w.Value.([]query.OriginPoolWhereClause); ok {
				var orParts []string
				for _, sc := range subs {
					sub, subArgs := buildOriginPoolWhere(c, []query.OriginPoolWhereClause{sc}, argIdx)
					if sub != "" {
						orParts = append(orParts, sub)
					}
					args = append(args, subArgs...)
				}
				if len(orParts) > 0 {
					parts = append(parts, "("+strings.Join(orParts, " OR ")+")")
				}
			}
		case "__NOT__":
			if sc, ok := w.Value.(query.OriginPoolWhereClause); ok {
				sub, subArgs := buildOriginPoolWhere(c, []query.OriginPoolWhereClause{sc}, argIdx)
				if sub != "" {
					parts = append(parts, "NOT ("+sub+")")
				}
				args = append(args, subArgs...)
			}
		default:
			switch w.Operator {
			case "IS NULL":
				parts = append(parts, w.Field+" IS NULL")
			case "IN", "NOT IN":
				if vals, ok := w.Value.([]any); ok {
					if len(vals) == 0 {
						if w.Operator == "IN" {
							parts = append(parts, "1 = 0")
						} else {
							parts = append(parts, "1 = 1")
						}
					} else {
						phs := make([]string, len(vals))
						for i, v := range vals {
							*argIdx++
							phs[i] = c.placeholder(*argIdx)
							args = append(args, v)
						}
						parts = append(parts, w.Field+" "+w.Operator+" ("+strings.Join(phs, ", ")+")")
					}
				}
			case "CONTAINS":
				*argIdx++
				parts = append(parts, w.Field+" LIKE "+c.placeholder(*argIdx)+" ESCAPE '\\'")
				args = append(args, "%"+escapeLikePattern(fmt.Sprint(w.Value))+"%")
			case "STARTS_WITH":
				*argIdx++
				parts = append(parts, w.Field+" LIKE "+c.placeholder(*argIdx)+" ESCAPE '\\'")
				args = append(args, escapeLikePattern(fmt.Sprint(w.Value))+"%")
			case "ENDS_WITH":
				*argIdx++
				parts = append(parts, w.Field+" LIKE "+c.placeholder(*argIdx)+" ESCAPE '\\'")
				args = append(args, "%"+escapeLikePattern(fmt.Sprint(w.Value)))
			default:
				*argIdx++
				parts = append(parts, w.Field+" "+w.Operator+" "+c.placeholder(*argIdx))
				args = append(args, w.Value)
			}
		}
	}
	return strings.Join(parts, " AND "), args
}

