// Do executes the bulk insert and returns total affected rows.
func (b PolicyCreateManyBuilder) Do(ctx context.Context) (int64, error) {
	if len(b.data) == 0 {
		return 0, nil
	}
	batchSize := b.batchSize
	if batchSize <= 0 || batchSize > len(b.data) {
		batchSize = len(b.data)
	}
	var total int64
	for start := 0; start < len(b.data); start += batchSize {
		end := start + batchSize
		if end > len(b.data) {
			end = len(b.data)
		}
		q, args := b.action.buildPolicyCreateManySQL(b.data[start:end], b.conflictDoNothing, b.conflictColumns, nil)
		result, err := b.action.client.executor.ExecContext(ctx, q, args...)
		if err != nil {
			return total, fmt.Errorf("Policy.BulkCreate: %w", err)
		}
		n, err := result.RowsAffected()
		if err != nil {
			return total, fmt.Errorf("Policy.BulkCreate rows affected: %w", err)
		}
		total += n
	}
	return total, nil
}

// DoReturning executes the bulk insert and returns inserted rows.
func (b PolicyCreateManyBuilder) DoReturning(ctx context.Context) ([]model.Policy, error) {
	if b.action.client.dialect != "postgresql" {
		return nil, fmt.Errorf("Policy.BulkCreate.DoReturning: RETURNING is only supported for postgresql")
	}
	if len(b.returningColumns) > 0 {
		return nil, fmt.Errorf("Policy.BulkCreate.DoReturning: custom returning columns require DoReturningValues")
	}
	if len(b.data) == 0 {
		return nil, nil
	}
	batchSize := b.batchSize
	if batchSize <= 0 || batchSize > len(b.data) {
		batchSize = len(b.data)
	}
	var results []model.Policy
	for start := 0; start < len(b.data); start += batchSize {
		end := start + batchSize
		if end > len(b.data) {
			end = len(b.data)
		}
		q, args := b.action.buildPolicyCreateManySQL(b.data[start:end], b.conflictDoNothing, b.conflictColumns, []string{"id", "name", "cache_json", "waf_json", "cc_json", "access_json", "created_at", "updated_at"})
		rows, err := b.action.client.executor.QueryContext(ctx, q, args...)
		if err != nil {
			return nil, fmt.Errorf("Policy.BulkCreate.DoReturning: %w", err)
		}
		for rows.Next() {
			var item model.Policy
			if err := rows.Scan(&item.Id, &item.Name, &item.CacheJson, &item.WafJson, &item.CcJson, &item.AccessJson, &item.CreatedAt, &item.UpdatedAt); err != nil {
				_ = rows.Close()
				return nil, fmt.Errorf("Policy.BulkCreate.DoReturning scan: %w", err)
			}
			results = append(results, item)
		}
		if err := rows.Err(); err != nil {
			_ = rows.Close()
			return nil, fmt.Errorf("Policy.BulkCreate.DoReturning rows: %w", err)
		}
		if err := rows.Close(); err != nil {
			return nil, fmt.Errorf("Policy.BulkCreate.DoReturning close: %w", err)
		}
	}
	return results, nil
}

// DoReturningValues executes the bulk insert and returns selected column values.
func (b PolicyCreateManyBuilder) DoReturningValues(ctx context.Context) ([]map[string]any, error) {
	if b.action.client.dialect != "postgresql" {
		return nil, fmt.Errorf("Policy.BulkCreate.DoReturningValues: RETURNING is only supported for postgresql")
	}
	if len(b.data) == 0 {
		return nil, nil
	}
	returningColumns := b.returningColumns
	if len(returningColumns) == 0 {
		returningColumns = []string{"id", "name", "cache_json", "waf_json", "cc_json", "access_json", "created_at", "updated_at"}
	}
	batchSize := b.batchSize
	if batchSize <= 0 || batchSize > len(b.data) {
		batchSize = len(b.data)
	}
	var results []map[string]any
	for start := 0; start < len(b.data); start += batchSize {
		end := start + batchSize
		if end > len(b.data) {
			end = len(b.data)
		}
		q, args := b.action.buildPolicyCreateManySQL(b.data[start:end], b.conflictDoNothing, b.conflictColumns, returningColumns)
		rows, err := b.action.client.executor.QueryContext(ctx, q, args...)
		if err != nil {
			return nil, fmt.Errorf("Policy.BulkCreate.DoReturningValues: %w", err)
		}
		batch, err := scanRowsToMaps(rows)
		closeErr := rows.Close()
		if err != nil {
			return nil, fmt.Errorf("Policy.BulkCreate.DoReturningValues scan: %w", err)
		}
		if closeErr != nil {
			return nil, fmt.Errorf("Policy.BulkCreate.DoReturningValues close: %w", closeErr)
		}
		results = append(results, batch...)
	}
	return results, nil
}

