// SiteCreateManyBuilder builds a bulk Site insert operation.
type SiteCreateManyBuilder struct {
	action            SiteActions
	data              []query.SiteCreateInput
	conflictDoNothing bool
	conflictColumns   []string
	returningColumns  []string
	batchSize         int
}

// BulkCreate starts a staged bulk Site insert operation.
func (a SiteActions) BulkCreate(data []query.SiteCreateInput) SiteCreateManyBuilder {
	return SiteCreateManyBuilder{action: a, data: data}
}

// OnConflictDoNothing makes duplicate rows no-op instead of failing.
func (b SiteCreateManyBuilder) OnConflictDoNothing(columns ...string) SiteCreateManyBuilder {
	next := b
	next.conflictDoNothing = true
	next.conflictColumns = append([]string(nil), columns...)
	return next
}

// Returning sets the columns returned by DoReturningValues.
func (b SiteCreateManyBuilder) Returning(columns ...string) SiteCreateManyBuilder {
	next := b
	next.returningColumns = append([]string(nil), columns...)
	return next
}

// BatchSize limits how many rows are inserted per statement.
func (b SiteCreateManyBuilder) BatchSize(n int) SiteCreateManyBuilder {
	next := b
	next.batchSize = n
	return next
}

// Do executes the bulk insert and returns total affected rows.
func (b SiteCreateManyBuilder) Do(ctx context.Context) (int64, error) {
	if len(b.data) == 0 {
		return 0, nil
	}
	batchSize := b.batchSize
	if batchSize <= 0 || batchSize > len(b.data) {
		batchSize = len(b.data)
	}
	var total int64
	for start := 0; start < len(b.data); start += batchSize {
		end := start + batchSize
		if end > len(b.data) {
			end = len(b.data)
		}
		q, args := b.action.buildSiteCreateManySQL(b.data[start:end], b.conflictDoNothing, b.conflictColumns, nil)
		result, err := b.action.client.executor.ExecContext(ctx, q, args...)
		if err != nil {
			return total, fmt.Errorf("Site.BulkCreate: %w", err)
		}
		n, err := result.RowsAffected()
		if err != nil {
			return total, fmt.Errorf("Site.BulkCreate rows affected: %w", err)
		}
		total += n
	}
	return total, nil
}

// DoReturning executes the bulk insert and returns inserted rows.
func (b SiteCreateManyBuilder) DoReturning(ctx context.Context) ([]model.Site, error) {
	if b.action.client.dialect != "postgresql" {
		return nil, fmt.Errorf("Site.BulkCreate.DoReturning: RETURNING is only supported for postgresql")
	}
	if len(b.returningColumns) > 0 {
		return nil, fmt.Errorf("Site.BulkCreate.DoReturning: custom returning columns require DoReturningValues")
	}
	if len(b.data) == 0 {
		return nil, nil
	}
	batchSize := b.batchSize
	if batchSize <= 0 || batchSize > len(b.data) {
		batchSize = len(b.data)
	}
	var results []model.Site
	for start := 0; start < len(b.data); start += batchSize {
		end := start + batchSize
		if end > len(b.data) {
			end = len(b.data)
		}
		q, args := b.action.buildSiteCreateManySQL(b.data[start:end], b.conflictDoNothing, b.conflictColumns, []string{"id", "hostname", "status", "origin_pool_id", "policy_id", "version", "created_at", "updated_at"})
		rows, err := b.action.client.executor.QueryContext(ctx, q, args...)
		if err != nil {
			return nil, fmt.Errorf("Site.BulkCreate.DoReturning: %w", err)
		}
		for rows.Next() {
			var item model.Site
			if err := rows.Scan(&item.Id, &item.Hostname, &item.Status, &item.OriginPoolId, &item.PolicyId, &item.Version, &item.CreatedAt, &item.UpdatedAt); err != nil {
				_ = rows.Close()
				return nil, fmt.Errorf("Site.BulkCreate.DoReturning scan: %w", err)
			}
			results = append(results, item)
		}
		if err := rows.Err(); err != nil {
			_ = rows.Close()
			return nil, fmt.Errorf("Site.BulkCreate.DoReturning rows: %w", err)
		}
		if err := rows.Close(); err != nil {
			return nil, fmt.Errorf("Site.BulkCreate.DoReturning close: %w", err)
		}
	}
	return results, nil
}

// DoReturningValues executes the bulk insert and returns selected column values.
func (b SiteCreateManyBuilder) DoReturningValues(ctx context.Context) ([]map[string]any, error) {
	if b.action.client.dialect != "postgresql" {
		return nil, fmt.Errorf("Site.BulkCreate.DoReturningValues: RETURNING is only supported for postgresql")
	}
	if len(b.data) == 0 {
		return nil, nil
	}
	returningColumns := b.returningColumns
	if len(returningColumns) == 0 {
		returningColumns = []string{"id", "hostname", "status", "origin_pool_id", "policy_id", "version", "created_at", "updated_at"}
	}
	batchSize := b.batchSize
	if batchSize <= 0 || batchSize > len(b.data) {
		batchSize = len(b.data)
	}
	var results []map[string]any
	for start := 0; start < len(b.data); start += batchSize {
		end := start + batchSize
		if end > len(b.data) {
			end = len(b.data)
		}
		q, args := b.action.buildSiteCreateManySQL(b.data[start:end], b.conflictDoNothing, b.conflictColumns, returningColumns)
		rows, err := b.action.client.executor.QueryContext(ctx, q, args...)
		if err != nil {
			return nil, fmt.Errorf("Site.BulkCreate.DoReturningValues: %w", err)
		}
		batch, err := scanRowsToMaps(rows)
		closeErr := rows.Close()
		if err != nil {
			return nil, fmt.Errorf("Site.BulkCreate.DoReturningValues scan: %w", err)
		}
		if closeErr != nil {
			return nil, fmt.Errorf("Site.BulkCreate.DoReturningValues close: %w", closeErr)
		}
		results = append(results, batch...)
	}
	return results, nil
}

